<template><view class="p"><jk-page-nav title="佣金明细"/><view v-for="x in list" :key="x.id" class="card" @click="go(x.id)"><b>¥ {{x.commissionAmount}}</b><text>{{x.sourceTypeText || sourceTypeText(x.sourceType)}} · {{x.commissionStatusText || x.statusText || commissionStatusText(x.status)}}</text><text>收益人：{{x.applicantName || '用户不存在'}}<text v-if="x.applicantPhone"> / {{x.applicantPhone}}</text><text v-if="x.roleName"> / {{x.roleName}}</text></text><text>{{x.createTime}}</text></view><view v-if="!list.length" class="empty">暂无佣金记录</view></view></template><script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import{getJkCommissionList}from'@/api/jk.js';import{jkCommissionStatusText,jkSourceTypeText}from'@/utils/jk-display.js';export default{components:{JkPageNav},data(){return{list:[]}},onShow(){getJkCommissionList().then(r=>this.list=r.data||r||[])},methods:{commissionStatusText(status){return jkCommissionStatusText(status)},sourceTypeText(sourceType){return jkSourceTypeText(sourceType)},go(id){uni.navigateTo({url:'/pages/jk/commission/detail?id='+id})}}}</script><style scoped>.p{min-height:100vh;background:#f3fbf8;padding:24rpx}.card{margin-bottom:18rpx;padding:28rpx;background:#fff;border-radius:18rpx;display:flex;flex-direction:column;gap:10rpx}.card b{color:#1f9a75;font-size:36rpx}.card text{color:#708982;font-size:24rpx}.empty{text-align:center;color:#999;padding:80rpx}</style>
